import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"产品范围与架构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"architecture/lab-word.md","filePath":"architecture/lab-word.md"}'),n={name:"architecture/lab-word.md"};function o(i,a,l,s,c,p){return e(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="产品范围与架构" tabindex="-1">产品范围与架构 <a class="header-anchor" href="#产品范围与架构" aria-label="Permalink to &quot;产品范围与架构&quot;">​</a></h1><p>Lab Word 的产品目标是实验室数字孪生。当前应用提供持久 Lab、独立 Entity、多节点场景、服务器资产库和版本化定义。用户可以编辑布局、登记人工关系，并运行后端照明、温度与离心程序。术语见 <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>。</p><h2 id="模型与设备的关系" tabindex="-1">模型与设备的关系 <a class="header-anchor" href="#模型与设备的关系" aria-label="Permalink to &quot;模型与设备的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──登记──&gt; Entity（设备等对象）&lt;──定义── Asset</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 └──由 Scene Node 呈现 &lt;──外观── Asset Representation</span></span></code></pre></div><p>这是当前已建立的 Foundation V1 身份关系：Equipment Model 是三维资产表示，Equipment Instance 是设备类 Entity；Scene Node 的身份与摆放独立于设备身份。同一模型可表示多台设备，同一设备也可有多个节点。登记时固定定义版本及快照；模拟与真实对象保留独立身份，静态对象无需 Binding。</p><h2 id="已有实现与目标接入" tabindex="-1">已有实现与目标接入 <a class="header-anchor" href="#已有实现与目标接入" aria-label="Permalink to &quot;已有实现与目标接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>当前状态</th><th>后续责任</th></tr></thead><tbody><tr><td>通用应用壳、身份、成员、知识库</td><td>现有应用代码</td><td>为 Lab 提供宿主与共享能力</td></tr><tr><td>Lab 与持久资产库</td><td>Member/Agent 共用世界、布局、文件、设备程序、历史和生命周期操作</td><td>扩展大型资产的容量证据</td></tr><tr><td>Lab 导航与登录后默认入口</td><td>已由显式组装接入</td><td>保持宿主和 Lab 职责分离</td></tr><tr><td>Foundation V1</td><td>综合旅程及独立 100 Entity / 20 台设备 / 双浏览器报告已实现</td><td>根据记录的证据演进</td></tr><tr><td>真实设备与协议接入</td><td>后续范围</td><td>按实际来源增加适配与执行合同</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>选择复用现有 SaaS 底座：Lab 拥有设备与布局业务，Core 保持身份、成员等公共职责。接入点见<a href="./project-structure">项目结构</a>。</p><h2 id="当前呈现层边界" tabindex="-1">当前呈现层边界 <a class="header-anchor" href="#当前呈现层边界" aria-label="Permalink to &quot;当前呈现层边界&quot;">​</a></h2><p>Lab 主入口使用对象目录、多节点场景和 Inspector。摆放、配置与引用可在浏览器和 Agent 之间恢复。指针变换只编辑 Placement。用户显式登记带人工来源的关系。API 拒绝非法空间环。复制创建独立 Entity。新增表示和移除节点保留身份。版本冲突保留草稿，并提供显式恢复。见<a href="./../tutorials/edit-layout">布局教程</a>。</p><p>定义支持、Binding 实现和当前可执行性保持独立。没有观测时显示未知。<a href="./../tutorials/backend-lights">后端照明</a>区分命令接受与观测。停止后保留最后报告。中断后必须显式启动。布局版本与运行态保持独立。<a href="./../tutorials/reliable-sync">世界订阅</a>提供持久版本、属性更新、有界队列与快照恢复。凭据撤销会结束已有访问。服务就绪与持久能力许可共同决定可操作性。</p><p><a href="./../tutorials/run-history">历史</a>支持设备、类型、时间范围和游标查询。原始观测默认保留 24 小时。已结束命令、任务和事件默认保留 30 天。清理保留身份、配置、最后逐属性观测与在途任务。每个保留属性保持实际时间与新鲜度。删除过期当前任务记录会推进世界版本。历史缺口保持明确。资产库在 <code>/lab/asset</code> 保留单模型预览。Core 管理文件生命周期。Lab 管理稳定引用。</p><p><a href="./../tutorials/entity-lifecycle">对象生命周期</a>要求 Task 结束、程序停止后才能归档或更换定义。归档保留身份、节点、真实资产引用和保留期内记录。程序或 Task 运行期间可以替换外观。替换更新 Entity 和当前节点，不改变设备行为。显式目录选择记录定义版本。支持运行的模拟定义获得新的当前 Binding。其他选择没有当前 Binding。旧 Run 保留原关联和来源。<a href="./../tutorials/complete-foundation">完整旅程</a>验证组合恢复，并提供独立参考负载命令。</p><p><a href="./../tutorials/continuous-temperature">温度传感器</a>在后端以 1Hz 独立采样。每个属性保留值、单位、来源、时间和质量。心跳不刷新旧测量。停止后保留最后值，并在报告期限后过期。过期推进世界版本，布局草稿不受影响。</p><p><a href="./../tutorials/centrifuge-tasks">离心任务</a>由后端推进，关闭浏览器不会结束任务。Command、Run、Task 和结果具有独立可查询身份。任务固定转速、温度和时长。转速与温度达标后才计时，准备和减速不计入任务时长。Stop 经减速后得到 cancelled，正常结束经减速后得到 completed。异常和不确定结果不能变为 completed。后端重启将原 Run 和未结束任务标为 interrupted。用户必须显式启动新 Run。内置转子根据观测 RPM 在客户端旋转，导入 GLB 没有转子映射。</p><p>当前实现保持模型原始尺度，并在外部资源依赖、无几何或解码失败时反馈错误、保留前一个可用模型。每个节点独立加载并释放模型资源，选择一个实例不改写其他实例材质；World 快照返回节点及未放置对象引用的资产，模型恢复不依赖目录第一页。</p><p>Three.js 相关代码已随 Lab 页面按需加载，并纳入正式包体预算。预览的构建与软件渲染指标不代表目标硬件性能。</p><h2 id="继续开发" tabindex="-1">继续开发 <a class="header-anchor" href="#继续开发" aria-label="Permalink to &quot;继续开发&quot;">​</a></h2><p>按<a href="./../tutorials/complete-foundation">完整旅程</a>跟做已交付的 Foundation V1 路径，并查看容量限制。真实设备、机器人运动和自主实验规划仍属后续范围。职责规则见<a href="./module-boundaries">模块边界</a>。</p><hr><p>源码版本：<code>a455a4dba0f3</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/architecture/lab-word.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,21)])])}const u=t(n,[["render",o]]);export{h as __pageData,u as default};
